import { clsx } from 'clsx';
import { extendTailwindMerge } from 'tailwind-merge';
import { fluidClassGroups } from './fluid.tokens.js';

// fluidClassGroups is generated by scripts/fluid.generate.mjs. It teaches
// tailwind-merge which conflict group each fluid class belongs to — without it,
// a class like `text-btn` is guessed to be a text *color* and would silently
// evict `text-white` (or be evicted by it).
const twMerge = extendTailwindMerge({ extend: { classGroups: fluidClassGroups } });

export function cn(...inputs) {
  return twMerge(clsx(inputs));
}
